<script lang="ts" module>import type {Snippet} from 'svelte';export interface DrawerProps{open?:boolean;placement?:'left'|'right'|'top'|'bottom';size?:string;overlay?:boolean;preventClose?:boolean;title?:string|Snippet;footer?:Snippet;children:Snippet;trigger?:Snippet;onOpenChange?:(open:boolean)=>void}</script>
<script lang="ts">import * as Sheet from '$lib/components/ui/sheet';let{open=$bindable(false),placement='left',size='20rem',overlay=true,preventClose=false,title,footer,children,trigger,onOpenChange}:DrawerProps=$props();function changed(value:boolean){open=value;onOpenChange?.(value)}function prevent(event:Event){if(preventClose)event.preventDefault()}</script>
<Sheet.Root bind:open onOpenChange={changed}>{#if trigger}<Sheet.Trigger class="rx-drawer__trigger">{@render trigger()}</Sheet.Trigger>{/if}<Sheet.Content side={placement} class={`rx-drawer${!overlay?' rx-drawer--no-overlay':''}`} style={`--rx-drawer-size:${size}`} onEscapeKeydown={prevent} onInteractOutside={prevent}><div class="rx-drawer__head">{#if typeof title==='string'}<Sheet.Title>{title}</Sheet.Title>{:else if title}<Sheet.Title>{@render title()}</Sheet.Title>{/if}</div><div class="rx-drawer__body">{@render children()}</div>{#if footer}<Sheet.Footer>{@render footer()}</Sheet.Footer>{/if}</Sheet.Content></Sheet.Root>
<style>:global(body:has(.rx-drawer--no-overlay) [data-slot="sheet-overlay"]){display:none}:global(.rx-drawer){border:0!important;border-radius:var(--rx-radius);background:rgb(var(--rx-background));color:rgb(var(--rx-text));box-shadow:0 18px 50px rgb(var(--rx-dark)/.22)}:global(.rx-drawer[data-side=left]),:global(.rx-drawer[data-side=right]){width:min(92vw,var(--rx-drawer-size))!important;max-width:none!important}:global(.rx-drawer[data-side=top]),:global(.rx-drawer[data-side=bottom]){height:min(92vh,var(--rx-drawer-size))!important}:global(.rx-drawer--no-overlay){position:fixed}.rx-drawer__head{padding:1.25rem 1.25rem 0}.rx-drawer__body{min-height:0;flex:1;overflow:auto;padding:1.25rem}@media(prefers-reduced-motion:reduce){:global(.rx-drawer){animation:none!important;transition:none!important}}</style>
